// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 depositAmount, bool doWithdraw) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        try c.deposit{value: depositAmount}() {} catch { return; }
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalBefore = address(c).balance;
        bool reverted2;
        try c.withdrawAll() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint cBalAfter = address(c).balance;
        assertTrue(reverted || cBalAfter >= cBalBefore);
    }

    function testFuzz_run(uint256 depositAmount, bool doWithdraw) public {
        _run(depositAmount, doWithdraw);
    }

    receive() external payable {}
}
